type Tree = Empty | Leaf(int) | Branch(Tree, int, Tree)

pure func treeSum(t: Tree) -> int =
  match t {
    Empty => 0,
    Leaf(n) => n,
    Branch(left, n, right) => treeSum(left) + n + treeSum(right)
  }

export func main() -> () ! {IO} {
  let tree = Branch(
    Branch(Leaf(1), 3, Leaf(4)),
    5,
    Branch(Empty, 8, Leaf(10))
  );
  println(show(treeSum(tree)))
}

